import { Controller, Get, Post, Put, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '급여 담당자';
const CLOSED_STATUSES = ['마감', '전표처리'];
const STATUSES = ['등록', '계산완료', '과세집계완료', '마감', '전표처리', '마감취소'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function textOf(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function paydayIdOf(raw: string | undefined): string {
  const text = textOf(raw);
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '급여 지급일 ID 형식이 올바르지 않습니다.');
  }
  return text;
}

function employeeIdsOf(value: unknown): number[] {
  if (!Array.isArray(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '급여 대상 임직원 ID 목록은 배열이어야 합니다.');
  }
  const ids: number[] = [];
  for (const item of value) {
    const id = Number(item);
    if (item === '' || item === null || !Number.isInteger(id) || id <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 대상 임직원 ID는 숫자여야 합니다.');
    }
    if (!ids.includes(id)) {
      ids.push(id);
    }
  }
  return ids;
}

@Controller('api/v1')
export class FnSfr02101Controller {
  @Get('/paydays')
  async listPaydays(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const payDateFrom = textOf(query['payDateFrom']);
    const payDateTo = textOf(query['payDateTo']);
    const status = textOf(query['status']);
    if (payDateFrom && !DATE_PATTERN.test(payDateFrom)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '지급일 조회 시작일 형식이 올바르지 않습니다.');
    }
    if (payDateTo && !DATE_PATTERN.test(payDateTo)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '지급일 조회 종료일 형식이 올바르지 않습니다.');
    }
    if (status && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 상태 값이 올바르지 않습니다.');
    }
    const pageNo = Number(textOf(query['page']) || '0');
    const sizeNo = Number(textOf(query['size']) || '20');
    if (!Number.isInteger(pageNo) || pageNo < 0 || !Number.isInteger(sizeNo) || sizeNo < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
    }
    const size = Math.min(sizeNo, 200);
    return transaction(async (db) => {
      const conditions: string[] = [];
      const params: Record<string, unknown> = {};
      if (payDateFrom) {
        conditions.push('pay_date >= CAST(:payDateFrom AS date)');
        params['payDateFrom'] = payDateFrom;
      }
      if (payDateTo) {
        conditions.push('pay_date <= CAST(:payDateTo AS date)');
        params['payDateTo'] = payDateTo;
      }
      if (status) {
        conditions.push('status = :status');
        params['status'] = status;
      }
      const where = conditions.length > 0 ? 'WHERE ' + conditions.join(' AND ') : '';
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM payday ' + where,
        params,
      );
      const items = await db.query(
        'SELECT payday_id AS "paydayId", pay_date AS "payDate", pay_type AS "payType", status AS "status" ' +
          'FROM payday ' +
          where +
          ' ORDER BY pay_date DESC, payday_id DESC OFFSET :offset LIMIT :limit',
        { ...params, offset: pageNo * size, limit: size },
      );
      // 가정: 급여 대상자 수(targetCount)는 payroll 행 수이나 schema.sql에 payroll 테이블이 없어 TODO로 남긴다.
      return { items, page: pageNo, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/paydays')
  @HttpCode(200)
  async createPayday(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const payDate = textOf(data['payDate']);
    const payType = textOf(data['payType']);
    if (!payDate) {
      throw new ApiError(422, 'PAYDAY_INVALID', '급여 지급일을 입력해 주세요.');
    }
    if (!DATE_PATTERN.test(payDate)) {
      throw new ApiError(422, 'PAYDAY_INVALID', '급여 지급일 형식이 올바르지 않습니다.');
    }
    if (!payType) {
      throw new ApiError(422, 'PAYDAY_INVALID', '급여 구분을 입력해 주세요.');
    }
    if (payType.length > 50) {
      throw new ApiError(422, 'PAYDAY_INVALID', '급여 구분은 50자 이내로 입력해 주세요.');
    }
    if (data['employeeIds'] === undefined || data['employeeIds'] === null) {
      throw new ApiError(422, 'PAYDAY_INVALID', '급여 대상 임직원을 지정해 주세요.');
    }
    employeeIdsOf(data['employeeIds']);
    return transaction(async (db) => {
      const dup = await db.query(
        'SELECT payday_id FROM payday WHERE pay_date = CAST(:payDate AS date) AND pay_type = :payType',
        { payDate, payType },
      );
      if (dup.length > 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '같은 지급일과 급여 구분이 이미 등록되어 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO payday (pay_date, pay_type, status, created_at, updated_at) ' +
          "VALUES (CAST(:payDate AS date), :payType, '등록', now(), now()) " +
          'RETURNING payday_id AS "paydayId"',
        { payDate, payType },
      );
      // TODO: 급여 대상 임직원 저장 (employee·payroll 테이블이 schema.sql에 없음)
      return { paydayId: Number(rows[0]['paydayId']) };
    });
  }

  @Put('/paydays/:paydayId/targets')
  async replacePaydayTargets(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const paydayId = paydayIdOf(req.params['paydayId']);
    const data = checks.inputOf(req.body);
    if (data['employeeIds'] === undefined || data['employeeIds'] === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 대상 임직원 ID 목록을 보내 주세요.');
    }
    employeeIdsOf(data['employeeIds']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM payday WHERE payday_id = CAST(:paydayId AS bigint) FOR UPDATE',
        { paydayId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PAYDAY_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
      }
      if (CLOSED_STATUSES.includes(String(rows[0]['status']))) {
        throw new ApiError(409, 'PAYDAY_CLOSED', '마감된 지급일입니다. 마감취소 후 대상을 변경해 주세요.');
      }
      // TODO: 급여 대상 임직원 교체 저장 (employee·payroll 테이블이 schema.sql에 없음)
      await db.execute(
        'UPDATE payday SET updated_at = now() WHERE payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      return { paydayId: Number(paydayId) };
    });
  }

  @Patch('/paydays/:paydayId')
  async updatePayday(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const paydayId = paydayIdOf(req.params['paydayId']);
    const data = checks.inputOf(req.body);
    const payDate = textOf(data['payDate']);
    const payType = textOf(data['payType']);
    if (payDate && !DATE_PATTERN.test(payDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 지급일 형식이 올바르지 않습니다.');
    }
    if (payType.length > 50) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 구분은 50자 이내로 입력해 주세요.');
    }
    if (!payDate && !payType) {
      throw new ApiError(400, 'VALIDATION_FAILED', '수정할 값을 입력해 주세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM payday WHERE payday_id = CAST(:paydayId AS bigint) FOR UPDATE',
        { paydayId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PAYDAY_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
      }
      if (CLOSED_STATUSES.includes(String(rows[0]['status']))) {
        throw new ApiError(409, 'PAYDAY_CLOSED', '마감된 지급일은 수정할 수 없습니다.');
      }
      const params = { paydayId, payDate: payDate || null, payType: payType || null };
      const dup = await db.query(
        'SELECT p.payday_id FROM payday p, payday cur ' +
          'WHERE cur.payday_id = CAST(:paydayId AS bigint) AND p.payday_id <> cur.payday_id ' +
          'AND p.pay_date = COALESCE(CAST(:payDate AS date), cur.pay_date) ' +
          'AND p.pay_type = COALESCE(CAST(:payType AS varchar), cur.pay_type)',
        params,
      );
      if (dup.length > 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '같은 지급일과 급여 구분이 이미 등록되어 있습니다.');
      }
      await db.execute(
        'UPDATE payday SET pay_date = COALESCE(CAST(:payDate AS date), pay_date), ' +
          'pay_type = COALESCE(CAST(:payType AS varchar), pay_type), updated_at = now() ' +
          'WHERE payday_id = CAST(:paydayId AS bigint)',
        params,
      );
      return { paydayId: Number(paydayId) };
    });
  }

  @Delete('/paydays/:paydayId')
  async deletePayday(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const paydayId = paydayIdOf(req.params['paydayId']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM payday WHERE payday_id = CAST(:paydayId AS bigint) FOR UPDATE',
        { paydayId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PAYDAY_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
      }
      if (CLOSED_STATUSES.includes(String(rows[0]['status']))) {
        throw new ApiError(409, 'PAYDAY_CLOSED', '마감된 지급일은 삭제할 수 없습니다.');
      }
      await db.execute(
        'DELETE FROM payday WHERE payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      return {};
    });
  }
}

