import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const ROLE = '급여 담당자';
const STATUS_OPTIONS: [string, string][] = [
  ['등록', '등록'],
  ['계산완료', '계산완료'],
  ['과세집계완료', '과세집계완료'],
  ['마감', '마감'],
  ['전표처리', '전표처리'],
  ['마감취소', '마감취소'],
];
const SIZE = 20;

type Mode =
  | { kind: 'create' }
  | { kind: 'edit'; row: Row }
  | { kind: 'targets'; row: Row }
  | { kind: 'delete'; row: Row };

function isClosed(row: Row): boolean {
  return row['status'] === '마감' || row['status'] === '전표처리';
}

function TargetPicker({ ids, onChange }: { ids: number[]; onChange: (ids: number[]) => void }) {
  const [pick, setPick] = useState<number | string>('');
  return (
    <div>
      <LookupSelect
        table="employee"
        role={ROLE}
        value={pick}
        placeholder="임직원 선택"
        onChange={(v) => {
          const id = Number(v);
          if (v !== '' && id > 0 && !ids.includes(id)) {
            onChange([...ids, id]);
          }
          setPick('');
        }}
      />
      <ul>
        {ids.map((id) => (
          <li key={id}>
            <RefName table="employee" role={ROLE} value={id} />
            <button type="button" onClick={() => onChange(ids.filter((x) => x !== id))}>
              제거
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default function FnSfr02101Page({ role, notify }: PageProps) {
  const [payDateFrom, setPayDateFrom] = useState('');
  const [payDateTo, setPayDateTo] = useState('');
  const [status, setStatus] = useState('');
  const [applied, setApplied] = useState({ payDateFrom: '', payDateTo: '', status: '' });
  const [pageNo, setPageNo] = useState(0);
  const [mode, setMode] = useState<Mode | null>(null);
  const [payDate, setPayDate] = useState('');
  const [payType, setPayType] = useState('');
  const [employeeIds, setEmployeeIds] = useState<number[]>([]);

  const list = useData<Page>(
    () =>
      call<Page>('GET', '/paydays', role, undefined, {
        payDateFrom: applied.payDateFrom,
        payDateTo: applied.payDateTo,
        status: applied.status,
        page: pageNo,
        size: SIZE,
      }),
    [applied, pageNo, role],
  );

  const rows = list.data?.items ?? [];
  const total = list.data?.total ?? 0;
  const closedCount = rows.filter((r) => isClosed(r)).length;

  function openCreate() {
    setPayDate('');
    setPayType('');
    setEmployeeIds([]);
    setMode({ kind: 'create' });
  }

  function openEdit(row: Row) {
    setPayDate(String(row['payDate'] ?? ''));
    setPayType(String(row['payType'] ?? ''));
    setMode({ kind: 'edit', row });
  }

  function openTargets(row: Row) {
    setEmployeeIds([]);
    setMode({ kind: 'targets', row });
  }

  function done(text: string) {
    setMode(null);
    notify(text);
    list.reload();
  }

  async function create() {
    if (!payDate) {
      throw new Error('급여 지급일을 입력해 주세요.');
    }
    if (!payType.trim()) {
      throw new Error('급여 구분을 입력해 주세요.');
    }
    await call('POST', '/paydays', role, { payDate, payType: payType.trim(), employeeIds });
    done('급여 지급일을 등록했습니다.');
  }

  async function edit(row: Row) {
    if (!payDate || !payType.trim()) {
      throw new Error('급여 지급일과 급여 구분을 입력해 주세요.');
    }
    await call('PATCH', '/paydays/' + String(row['paydayId']), role, {
      payDate,
      payType: payType.trim(),
    });
    done('급여 지급일을 수정했습니다.');
  }

  async function saveTargets(row: Row) {
    await call('PUT', '/paydays/' + String(row['paydayId']) + '/targets', role, { employeeIds });
    done('급여 대상을 변경했습니다.');
  }

  async function remove(row: Row) {
    await call('DELETE', '/paydays/' + String(row['paydayId']), role);
    done('급여 지급일을 삭제했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>지급일 현황</h2>
        <Tiles
          items={[
            ['전체 지급일', total],
            ['이 쪽의 마감 건수', closedCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>급여 지급일</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setApplied({ payDateFrom, payDateTo, status });
          }}
          onReset={() => {
            setPayDateFrom('');
            setPayDateTo('');
            setStatus('');
            setPageNo(0);
            setApplied({ payDateFrom: '', payDateTo: '', status: '' });
          }}
        >
          <Field label="지급일 조회 시작일">
            <DateInput value={payDateFrom} onChange={setPayDateFrom} />
          </Field>
          <Field label="지급일 조회 종료일">
            <DateInput value={payDateTo} onChange={setPayDateTo} />
          </Field>
          <Field label="처리 상태">
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={openCreate}>
            지급일 등록
          </button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          rows={rows}
          empty="등록된 급여 지급일이 없습니다."
          columns={[
            { key: 'paydayId', label: '급여 지급일 ID' },
            { key: 'payDate', label: '급여 지급일', render: (r) => <DateText value={r['payDate']} /> },
            { key: 'payType', label: '급여 구분' },
            { key: 'status', label: '처리 상태', render: (r) => <Badge value={r['status']} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) =>
                isClosed(r) ? (
                  <span>-</span>
                ) : (
                  <span>
                    <button type="button" onClick={() => openEdit(r)}>
                      수정
                    </button>
                    <button type="button" onClick={() => openTargets(r)}>
                      대상 변경
                    </button>
                    <button type="button" onClick={() => setMode({ kind: 'delete', row: r })}>
                      삭제
                    </button>
                  </span>
                ),
            },
          ]}
        />
        <Pager page={pageNo} size={SIZE} total={total} onPage={setPageNo} />
      </section>
      {mode && mode.kind === 'create' ? (
        <Drawer title="급여 지급일 등록" onClose={() => setMode(null)}>
          <Form onSubmit={create} submit="등록">
            <Field label="급여 지급일" required>
              <DateInput value={payDate} onChange={setPayDate} />
            </Field>
            <Field label="급여 구분" required>
              <TextInput value={payType} onChange={setPayType} />
            </Field>
            <Field label="급여 대상 임직원" wide>
              <TargetPicker ids={employeeIds} onChange={setEmployeeIds} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {mode && mode.kind === 'edit' ? (
        <Drawer title="급여 지급일 수정" onClose={() => setMode(null)}>
          <Form onSubmit={() => edit(mode.row)} submit="저장">
            <Field label="급여 지급일" required>
              <DateInput value={payDate} onChange={setPayDate} />
            </Field>
            <Field label="급여 구분" required>
              <TextInput value={payType} onChange={setPayType} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {mode && mode.kind === 'targets' ? (
        <Drawer title="급여 대상 변경" onClose={() => setMode(null)}>
          <Form
            onSubmit={() => saveTargets(mode.row)}
            submit="대상 저장"
            note="선택한 임직원으로 급여 대상 전체가 바뀝니다."
          >
            <Field label="급여 대상 임직원" wide>
              <TargetPicker ids={employeeIds} onChange={setEmployeeIds} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {mode && mode.kind === 'delete' ? (
        <Drawer title="급여 지급일 삭제" onClose={() => setMode(null)}>
          <Form
            onSubmit={() => remove(mode.row)}
            submit="삭제"
            danger
            note="삭제한 급여 지급일은 되돌릴 수 없습니다."
          />
        </Drawer>
      ) : null}
    </div>
  );
}
